class MapPaint extends CustomPainter{
 @override void paint(Canvas c,Size s){c.drawRect(Offset.zero&s,Paint()..color=const Color(0xFF22262A));final road=Paint()..color=const Color(0xFF3B4145)..strokeWidth=8..style=PaintingStyle.stroke..strokeCap=StrokeCap.round;final minor=Paint()..color=const Color(0xFF30373B)..strokeWidth=3;final paths=[[Offset(-5,40),Offset(70,65),Offset(150,40),Offset(235,75),Offset(s.width+10,50)],[Offset(25,s.height+5),Offset(95,130),Offset(180,110),Offset(260,140),Offset(s.width,105)],[Offset(s.width*.62,-5),Offset(s.width*.57,65),Offset(s.width*.72,115),Offset(s.width*.68,s.height+5)]];for(final pts in paths){final p=Path()..moveTo(pts.first.dx,pts.first.dy);for(final q in pts.skip(1)){p.lineTo(q.dx,q.dy);}c.drawPath(p,road);}for(int i=0;i<4;i++){final y=20.0+i*42;c.drawLine(Offset(0,y),Offset(s.width,y+18),minor);}final route=Path()..moveTo(s.width*.18,s.height*.68)..cubicTo(s.width*.32,s.height*.45,s.width*.52,s.height*.76,s.width*.76,s.height*.35);c.drawPath(route,Paint()..color=gold..strokeWidth=3.5..style=PaintingStyle.stroke..strokeCap=StrokeCap.round);c.drawCircle(Offset(s.width*.18,s.height*.68),10,Paint()..color=gold.withOpacity(.2));c.drawCircle(Offset(s.width*.18,s.height*.68),5,Paint()..color=gold);c.drawCircle(Offset(s.width*.76,s.height*.35),6,Paint()..color=gold);}
 @override bool shouldRepaint(covariant CustomPainter old)=>false;
}
